import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> [side, price, qty, seq]
    seq_counter = 0

    def add_resting(oid, side, price, qty, seq):
        book[oid] = [side, price, qty, seq]
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    for order in orders:
        seq_counter += 1
        cmd = order[0]

        if cmd == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        if cmd == 'market':
            _, oid, side, qty = order
            price = None
        else:
            _, oid, side, price, qty = order

        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                p_top, seq_top, id_top = sell_heap[0]
                if id_top not in book or book[id_top][2] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                resting_price = book[id_top][1]
                if cmd != 'market' and price < resting_price:
                    break
                trade_qty = min(remaining, book[id_top][2])
                trades.append([oid, id_top, resting_price, trade_qty])
                remaining -= trade_qty
                book[id_top][2] -= trade_qty
                if book[id_top][2] == 0:
                    del book[id_top]
                    heapq.heappop(sell_heap)
            if remaining > 0 and cmd == 'limit':
                add_resting(oid, 'buy', price, remaining, seq_counter)

        else:  # sell
            while remaining > 0 and buy_heap:
                neg_p_top, seq_top, id_top = buy_heap[0]
                if id_top not in book or book[id_top][2] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                resting_price = book[id_top][1]
                if cmd != 'market' and price > resting_price:
                    break
                trade_qty = min(remaining, book[id_top][2])
                trades.append([id_top, oid, resting_price, trade_qty])
                remaining -= trade_qty
                book[id_top][2] -= trade_qty
                if book[id_top][2] == 0:
                    del book[id_top]
                    heapq.heappop(buy_heap)
            if remaining > 0 and cmd == 'limit':
                add_resting(oid, 'sell', price, remaining, seq_counter)

    return trades

